/**
 * @ohos/dsh-ontology — the user's durable, queryable self, on the device.
 *
 * The shell already had `user_profile`: a marked block inside AGENTS.md that
 * every session loads. It works for a dozen sentences, but it cannot answer
 * "who is my mother", cannot keep "I used to run, now I don't" from turning
 * into two contradictory facts, and cannot be audited or exported without
 * parsing prose. This plugin is the structured successor:
 *
 *   <DSH_HOME>/ontology/ontology.db      SQLite: entities + facts + history
 *   <DSH_HOME>/ontology/snapshot.json    what the app panel reads
 *   <DSH_HOME>/ontology/summary.md       human-readable export
 *   <DSH_HOME>/ontology/commands/*.json  one file per panel action (delete)
 *
 * Model surface:
 *   - `ontology` tool: remember / correct / forget / search / list / export.
 *   - pinned facts (identity, language, allergies, diet, communication style)
 *     are injected at the start of a session and whenever that set changes,
 *     through `agent/pre-step`; everything else is fetched on demand.
 *
 * Storage stays local, but facts injected into a prompt are sent to the model
 * provider like any other message — the docs are explicit about that.
 */
import { createUserMessage } from "@deepseek-ai/dsh-llm";
import { defineTool } from "@deepseek-ai/dsh-tools";
import {
	appendFileSync,
	chmodSync,
	existsSync,
	mkdirSync,
	readFileSync,
	readdirSync,
	renameSync,
	statSync,
	unlinkSync,
	watch,
	writeFileSync,
} from "node:fs";
import { createHash, randomUUID } from "node:crypto";
import { homedir } from "node:os";
import { basename, dirname, isAbsolute, join, resolve } from "node:path";
import { describeCatalog, describePredicates, predicateCatalog, predicateList, suggestPredicate } from "./lib/vocab.js";
import { buildSnapshot, renderMarkdown, renderPinned, renderTurtle } from "./lib/render.js";
import { runMetric } from "./lib/metrics.js";
import { mapLegacyFact, parseLegacyFacts, stripLegacyBlock } from "./lib/legacy-profile.js";
import { lineOf, recordOf } from "./lib/injection.js";

const name = "ontology";
const inject = ["tools", "agents"];
const TAG = "[ontology]";
const COMMAND_RE = /^fact_[0-9a-f]{8,32}$/;

/** @type {any} */
let store = null;
/** @type {any} */
let storeApi = null;
/** @type {Promise<any> | null} */
let ready = null;
/** @type {string | null} */
let initError = null;
/** @type {string} */
let dataDir = "";
/** @type {string} */
let commandDir = "";
/** @type {string} */
let dbPath = "";
/** @type {{at: string, ok: boolean, message: string} | null} */
let lastCommand = null;
/** @type {import('node:fs').FSWatcher | null} */
let watcher = null;
/** @type {NodeJS.Timeout | null} */
let timer = null;
/** @type {WeakMap<object, {version: number, signature: string, hadPinned: boolean}>} */
const injected = new WeakMap();

/** @returns {string} harness home. */
function harnessHome() {
	const configured = process.env.DSH_HOME;
	if (typeof configured === "string" && configured.length > 0) return configured;
	return join(homedir(), "dsh-home");
}

/**
 * The default project workspace. `DSH_HOME` is `<filesDir>/dsh-home`, so its
 * parent is the app files root; `HOME` is set to that root by NodeHost and is
 * preferred when the real workspace exists.
 * @returns {string} absolute workspace path.
 */
function workspaceRoot() {
	const home = process.env.HOME;
	if (typeof home === "string" && home.length > 0) {
		const candidate = join(home, "workspace");
		if (existsSync(candidate)) return candidate;
	}
	return join(dirname(harnessHome()), "workspace");
}

/** @param {string} target - path. @param {string} body - UTF-8 text. */
function writeAtomic(target, body) {
	const staging = `${target}.${randomUUID()}.tmp`;
	writeFileSync(staging, body, { encoding: "utf8", mode: 0o600 });
	try {
		chmodSync(staging, 0o600);
	} catch {
		/* the device may ignore mode bits on some mounts; the sandbox still applies */
	}
	renameSync(staging, target);
	try {
		chmodSync(target, 0o600);
	} catch {
		/* see above */
	}
}

/** Kept small: the chip only needs the latest few injections. */
const INJECTION_MAX_BYTES = 256 * 1024;

/**
 * Append one injection record for the app.
 *
 * ACP does not surface the durable user message this plugin prepends, so the
 * phone would otherwise have no way to say "本轮带入 N 条记忆". Synchronous on
 * purpose: the record must be on disk before the assistant message lands, and
 * one short line is cheaper than a race.
 */
function logInjection(sessionId, turn, step, facts, removed) {
	if (typeof sessionId !== "string" || sessionId.length === 0) return;
	try {
		const record = recordOf({ sessionId, turn, step, facts, removed });
		if (record === null) return;
		const file = join(dataDir, "injections.jsonl");
		appendFileSync(file, lineOf(record), { encoding: "utf8", mode: 0o600 });
		try {
			chmodSync(file, 0o600);
		} catch {
			/* the sandbox still applies */
		}
		if (statSync(file).size > INJECTION_MAX_BYTES) {
			renameSync(file, `${file}.1`);
		}
	} catch (error) {
		// A chip is an explanation, not a turn requirement; never fail a step.
		console.warn(`${TAG} injection log failed: ${error instanceof Error ? error.message : String(error)}`);
	}
}

/** Write the panel snapshot and the human-readable summary. */
function writeSnapshot() {
	if (store === null || storeApi === null) return;
	try {
		const overview = storeApi.overview(store);
		const facts = storeApi.liveFacts(store, 400);
		const deleted = storeApi.deletedFacts(store, 10);
		const snapshot = buildSnapshot(facts, overview, lastCommand, undefined, deleted);
		writeAtomic(join(dataDir, "snapshot.json"), JSON.stringify(snapshot, null, 2));
		const all = storeApi.liveFacts(store, 2000);
		writeAtomic(join(dataDir, "summary.md"), renderMarkdown(all, overview));
	} catch (error) {
		console.log(`${TAG} snapshot failed: ${error?.message ?? error}`);
	}
}

/**
 * One-time import of the legacy user_profile managed block from AGENTS.md.
 * Dry-run by default: `apply: false` only previews the mapping.
 * @param {boolean} apply - write facts, back up the file, clear the block.
 * @returns {{ok: boolean, count: number, imported: number, duplicates: number, failed: number, backup: string | null, preview: string[], message: string}} outcome.
 */
function migrateLegacyProfile(apply) {
	const file = join(harnessHome(), "AGENTS.md");
	let body = "";
	try {
		body = readFileSync(file, "utf8");
	} catch {
		return {
			ok: true,
			count: 0,
			imported: 0,
			duplicates: 0,
			skipped: 0,
			failed: 0,
			backup: null,
			preview: [],
			message: "no AGENTS.md; nothing to migrate",
		};
	}
	const facts = parseLegacyFacts(body);
	if (facts.length === 0) {
		return {
			ok: true,
			count: 0,
			imported: 0,
			duplicates: 0,
			skipped: 0,
			failed: 0,
			backup: null,
			preview: [],
			message: "no legacy user_profile block; nothing to migrate",
		};
	}
	const mapped = facts.map((fact) => ({ fact, ...mapLegacyFact(fact.text) }));
	const preview = mapped.map(({ fact, predicate, object, qualifier }) =>
		`${fact.date.length > 0 ? fact.date : "(no date)"} · ${predicate} = ${object}${qualifier ? ` (${qualifier})` : ""}`,
	);
	if (!apply) {
		return {
			ok: true,
			count: facts.length,
			imported: 0,
			duplicates: 0,
			skipped: 0,
			failed: 0,
			backup: null,
			preview,
			message: `dry-run: ${facts.length} legacy fact${facts.length === 1 ? "" : "s"} would be imported`,
		};
	}
	const backup = join(harnessHome(), `AGENTS.md.bak-${new Date().toISOString().replaceAll(":", "-").replaceAll(".", "-")}`);
	writeAtomic(backup, body);
	let imported = 0;
	let duplicates = 0;
	let skipped = 0;
	const failed = [];
	for (const { fact, predicate, object, qualifier } of mapped) {
		try {
			const outcome = storeApi.remember(store, {
				subject: "self",
				predicate,
				object,
				qualifier,
				source: "migrated",
				sourceKind: "migration",
				sourceRef: "AGENTS.md#user-profile",
				observedAt: fact.date.length > 0 ? `${fact.date}T00:00:00.000Z` : undefined,
				preserveNewer: true,
			});
			if (outcome.skipped) skipped++;
			else if (outcome.duplicate) duplicates++;
			else imported++;
		} catch (error) {
			failed.push(`${fact.text}: ${error?.message ?? error}`);
		}
	}
	if (failed.length > 0) {
		return {
			ok: false,
			count: facts.length,
			imported,
			duplicates,
			skipped,
			failed: failed.length,
			backup,
			preview: [...preview, ...failed],
			message: `imported ${imported}, duplicates ${duplicates}, skipped older ${skipped}, failed ${failed.length}; AGENTS.md left unchanged`,
		};
	}
	writeAtomic(file, stripLegacyBlock(body));
	writeSnapshot();
	return {
		ok: true,
		count: facts.length,
		imported,
		duplicates,
		skipped,
		failed: 0,
		backup,
		preview,
		message: `imported ${imported}, duplicates ${duplicates}, skipped older ${skipped}; legacy block cleared (backup: ${backup})`,
	};
}

/** Apply one UI command file; returns true when the store changed. */
function applyCommand(fileName) {
	const path = join(commandDir, fileName);
	let command;
	try {
		command = JSON.parse(readFileSync(path, "utf8"));
	} catch (error) {
		lastCommand = { at: new Date().toISOString(), ok: false, message: `bad command file: ${error?.message ?? error}` };
		try {
			unlinkSync(path);
		} catch {
			/* retried on the next tick */
		}
		return true;
	}
	try {
		const op = String(command.op ?? "");
		if (op === "export-bundle") {
			const written = exportOntology("bundle", true);
			lastCommand = {
				at: new Date().toISOString(),
				ok: true,
				message: `bundle: ${written.workspacePath ?? written.path}`,
			};
		} else if (op === "import-latest") {
			const outcome = importLatestBundle();
			lastCommand = {
				at: new Date().toISOString(),
				ok: outcome !== null,
				message: outcome === null
					? "no ontology bundle found under workspace/ontology"
					: `imported ${outcome.imported}, skipped ${outcome.skipped}, superseded ${outcome.superseded}, conflicts ${Array.isArray(outcome.conflicts) ? outcome.conflicts.length : 0}`,
			};
		} else {
			const factId = String(command.factId ?? "");
			if (!COMMAND_RE.test(factId)) throw new Error("invalid fact id");
			if (op !== "forget" && op !== "purge") throw new Error(`unsupported op ${JSON.stringify(op)}`);
			const outcome = storeApi.forget(store, { factId, hard: op === "purge" });
			lastCommand = {
				at: new Date().toISOString(),
				ok: true,
				message: `${op}: ${outcome.count} fact${outcome.count === 1 ? "" : "s"}`,
			};
		}
	} catch (error) {
		lastCommand = { at: new Date().toISOString(), ok: false, message: String(error?.message ?? error) };
	}
	try {
		unlinkSync(path);
	} catch {
		/* the next tick retries the unlink, not the operation */
	}
	return true;
}

/** Drain up to 20 queued panel commands. */
function drainCommands() {
	if (store === null) return;
	let names;
	try {
		names = readdirSync(commandDir).filter((entry) => entry.endsWith(".json")).slice(0, 20);
	} catch {
		return;
	}
	if (names.length === 0) return;
	let changed = false;
	for (const fileName of names) changed = applyCommand(fileName) || changed;
	if (changed) writeSnapshot();
}

/** Watch the command directory and poll as a fallback (fs.watch is advisory). */
function startCommands() {
	if (watcher !== null) return;
	try {
		watcher = watch(commandDir, { persistent: false }, () => drainCommands());
	} catch (error) {
		console.log(`${TAG} command watch unavailable: ${error?.message ?? error}`);
	}
	timer = setInterval(drainCommands, 1500);
	timer.unref?.();
}

/** Stop watcher and timer. */
function stopCommands() {
	if (watcher !== null) {
		try {
			watcher.close();
		} catch {
			/* already closed */
		}
		watcher = null;
	}
	if (timer !== null) {
		clearInterval(timer);
		timer = null;
	}
}

/**
 * Open the store, write the first snapshot, and start the command watcher.
 * Never throws: a failed store leaves the tool registered with an error text.
 * @returns {Promise<any | null>} the store API module, or null.
 */
async function init() {
	try {
		dataDir = join(harnessHome(), "ontology");
		commandDir = join(dataDir, "commands");
		dbPath = join(dataDir, "ontology.db");
		mkdirSync(dataDir, { recursive: true, mode: 0o700 });
		mkdirSync(commandDir, { recursive: true, mode: 0o700 });
		storeApi = await import("./lib/store.js");
		store = storeApi.openStore(dbPath);
		try {
			chmodSync(dbPath, 0o600);
		} catch {
			/* mode bits are advisory on this platform */
		}
		writeSnapshot();
		startCommands();
		const overview = storeApi.overview(store);
		console.log(
			`${TAG} ready version=${overview.version} facts=${overview.counts.facts} entities=${overview.counts.entities} pinned=${overview.counts.pinned} db=${dbPath}`,
		);
		return storeApi;
	} catch (error) {
		initError = String(error?.stack ?? error);
		store = null;
		console.log(`${TAG} unavailable: ${initError}`);
		return null;
	}
}

/**
 * Export the live ontology.
 * @param {string} format - `markdown` | `json` | `turtle` | `bundle`.
 * @param {boolean} [toWorkspace] - also copy the bundle into the default workspace for sync.
 * @returns {{path: string, workspacePath: string | null, bytes: number, format: string}} written file.
 */
function exportOntology(format, toWorkspace = false) {
	const facts = storeApi.liveFacts(store, 2000);
	const overview = storeApi.overview(store);
	const stamp = new Date().toISOString();
	let fileName;
	let body;
	if (format === "bundle") {
		// Timestamped on purpose: project sync refuses to overwrite an existing
		// path, so a fixed name would be skipped on the second sync.
		fileName = `ontology-bundle-${stamp.replaceAll(":", "-").replaceAll(".", "-")}.json`;
		body = JSON.stringify(storeApi.exportBundle(store), null, 2);
	} else if (format === "turtle") {
		fileName = "export.ttl";
		body = renderTurtle(facts, storeApi.listEntities(store), stamp);
	} else if (format === "json") {
		fileName = "export.json";
		body = JSON.stringify(buildSnapshot(facts, overview, lastCommand, stamp), null, 2);
	} else {
		fileName = "export.md";
		body = renderMarkdown(facts, overview, stamp);
	}
	const target = join(dataDir, fileName);
	writeAtomic(target, body);
	let workspacePath = null;
	if (toWorkspace) {
		const dir = join(workspaceRoot(), "ontology");
		mkdirSync(dir, { recursive: true, mode: 0o700 });
		workspacePath = join(dir, fileName);
		writeAtomic(workspacePath, body);
	}
	return { path: target, workspacePath, bytes: Buffer.byteLength(body, "utf8"), format };
}

/**
 * Import one bundle file. The path must stay inside the harness home so a
 * model-supplied path cannot read arbitrary device files.
 * @param {string} pathInput - absolute path or path relative to the harness home.
 * @returns {{entitiesCreated: number, imported: number, skipped: number, superseded: number, path: string}} outcome.
 */
function importOntologyFile(pathInput) {
	const raw = String(pathInput ?? "").trim();
	if (raw.length === 0) throw new Error("path is required");
	const home = harnessHome();
	const target = resolve(isAbsolute(raw) ? raw : join(home, raw));
	const homeRoot = resolve(home);
	// The workspace is a sibling of dsh-home, not inside it. Both live under
	// the app files root, which is the trust boundary for a model-supplied path.
	const filesRoot = resolve(process.env.HOME && process.env.HOME.length > 0 ? process.env.HOME : dirname(homeRoot));
	const inside = (root) => target === root || target.startsWith(`${root}/`);
	if (!inside(homeRoot) && !inside(filesRoot)) {
		throw new Error("path must stay inside the app files directory");
	}
	const bundle = JSON.parse(readFileSync(target, "utf8"));
	const outcome = storeApi.importBundle(store, bundle, { sourceRef: `bundle:${basename(target)}` });
	writeSnapshot();
	return { ...outcome, path: target };
}

/**
 * Import the newest bundle a project sync dropped into the default workspace.
 * @returns {object | null} outcome, or null when there is no bundle.
 */
function importLatestBundle() {
	const dir = join(workspaceRoot(), "ontology");
	let names = [];
	try {
		names = readdirSync(dir).filter((entry) => /^ontology-bundle-.*\.json$/.test(entry)).sort();
	} catch {
		return null;
	}
	if (names.length === 0) return null;
	const target = join(dir, names[names.length - 1]);
	const outcome = importOntologyFile(target);
	// Keep the imported bundle for audit but take it out of the "latest" slot:
	// otherwise a second tap would resurrect facts the user deleted after import.
	try {
		renameSync(target, `${target}.imported`);
	} catch {
		/* the import already succeeded; a failed rename only affects retry hygiene */
	}
	return outcome;
}

/** Build the one-line summary of a per-fact action. */
function factLine(api, fact) {
	return api.factLine(fact);
}

/**
 * Mount the tool, the pre-step injection, and the lifecycle cleanup.
 * @param {import('@deepseek-ai/cordis').Context} ctx - plugin context.
 */
function apply(ctx) {
	ready = init();

	ctx.effect(() => () => {
		stopCommands();
		try {
			storeApi?.closeStore(store);
		} catch {
			/* disposal must not throw */
		}
		store = null;
	}, "ontology.store");

	// A tool description says what it CAN do; a system section says when to do
	// it. Without this the model tends to wait for an explicit "remember".
	ctx.inject(["systemPrompt"], (systemCtx) => {
		systemCtx.systemPrompt.section({
			name: "ontology",
			order: 60,
			text:
				"You have a durable on-device ontology about this user. When the user states a stable fact about themselves " +
				"— name, language, timezone, allergy, diet, relationship, project, goal, or a promise — call `ontology` with " +
				"action 'remember' (or 'correct' if it replaces an earlier value). Set `source_kind: 'user'` when the user said " +
				"it explicitly; the default is 'model' for something you inferred. Do not ask permission for ordinary facts, " +
				"and do not store one-off conversation details, credentials, or identity numbers. Facts marked pinned are " +
				"injected automatically; never re-ask them. " +
				"When a question may need a relationship or a calculation, call `related` for one- or two-hop facts and " +
				"`metric` for age, days until a deadline, days since a meeting, or a count — do not do calendar arithmetic in " +
				"your head. If `search` returns coverage 'none', say that it is not recorded; never treat a missing fact as " +
				"false. Call `describe` when unsure which predicate a Chinese phrase maps to.",
		});
	});

	ctx.tools.register(defineTool({
		name: "ontology",
		description:
			"The user's durable on-device ontology: who they are, hard constraints, relationships, projects, goals, and promises. " +
			"Use it whenever the user reveals something that should still be true next month — not for what happened in this conversation. " +
			`Predicates: ${describePredicates()}. Call action='describe' for each predicate's meaning, synonyms, and examples. ` +
			"Rules: (1) `remember` when a durable fact appears; repeating the same fact is a no-op. " +
			"(2) If the user changes their mind, use `correct` with the fact id instead of adding a second contradictory value. " +
			"(3) Single-valued predicates (name, birthday, city, occupation, employer, language, timezone, communication_style) automatically supersede their old value. " +
			"(4) Relationships use subject='self', predicate='relation', object=<person>, qualifier=<role, e.g. mother/friend/client>; facts about that person use them as subject (e.g. subject='妈妈', predicate='birthday'). " +
			"(5) Predicates marked pinned (name, nickname, pronoun, language, timezone, allergy, diet, avoids, communication_style) are injected into every new session automatically — never re-ask them. " +
			"(6) Pass `effective_at` when the user says when a state started (e.g. 'since last year'); otherwise the fact is valid from now. A later effective_at replaces the current value; an earlier one is stored as history and does not replace it. " +
			"(7) Never record credentials, API keys, passwords, or identity numbers. " +
			"(8) To move the ontology to another device, export format 'bundle' with to_workspace=true, send the default project's ontology/ folder with project sync (NearLink or LAN), then on the other device call import with the synced path. " +
			"(9) `search` returns coverage: 'none' means no record, not that the fact is false; say so. `related` walks the entity graph (depth 1–2). `metric` computes age / days_until / days_since / count deterministically. " +
			"(10) `source_kind` records who asserted the fact: 'user' when the user said it explicitly, 'model' when you inferred it. " +
			`Actions: remember | correct | forget | search | list | describe | related | metric | export | import | migrate_profile. Unknown predicates are rejected; the valid list is ${predicateList()}.`,
		parameters: {
			action: {
				type: "string",
				required: true,
				description: "remember | correct | forget | search | list | describe | related | metric | export | import | migrate_profile",
			},
			entity: {
				type: "string",
				description: "related: entity name or id to walk from; default 'self'.",
			},
			depth: {
				type: "number",
				description: "related: 1 or 2 hops (default 1, max 2).",
			},
			predicates: {
				type: "string",
				description: "related: optional comma-separated predicates to keep (e.g. 'relation,works_on').",
			},
			name: {
				type: "string",
				description: "describe/metric: predicate name for describe; metric name (age | days_until | days_since | count).",
			},
			source_kind: {
				type: "string",
				description: "remember/correct: 'user' when the user said it explicitly, 'model' when inferred; default model.",
			},
			subject: {
				type: "string",
				description: "remember/search/forget/related/metric: entity name or id; use 'self' for the user.",
			},
			predicate: {
				type: "string",
				description: "remember/search/forget: one predicate from the vocabulary.",
			},
			object: {
				type: "string",
				description: "remember/correct: the literal or the other entity's name.",
			},
			qualifier: {
				type: "string",
				description: "relation: the role (mother/friend/client); otherwise optional.",
			},
			effective_at: {
				type: "string",
				description: "remember/correct: when the fact became true (ISO 8601 or YYYY-MM-DD); default now.",
			},
			fact_id: {
				type: "string",
				description: "correct/forget: the id shown in a previous result.",
			},
			query: {
				type: "string",
				description: "search/forget: substring matched against subject, predicate, object, and qualifier.",
			},
			limit: {
				type: "number",
				description: "search: maximum rows (default 20, max 100).",
			},
			history: {
				type: "boolean",
				description: "search: include superseded and retired facts.",
			},
			hard: {
				type: "boolean",
				description: "forget: permanently delete the row instead of retiring it (default false).",
			},
			format: {
				type: "string",
				description: "export: markdown (default) | json | turtle | bundle (for syncing to another device).",
			},
			to_workspace: {
				type: "boolean",
				description: "export bundle: also write to the default workspace's ontology/ folder so project sync can carry it.",
			},
			path: {
				type: "string",
				description: "import: path to a synced ontology-bundle JSON inside the app's files directory.",
			},
			apply: {
				type: "boolean",
				description: "migrate_profile: actually import; false/default is a dry-run preview.",
			},
		},
		timeoutMs: 15000,
		output: {
			schema: {
				type: "object",
				additionalProperties: false,
				properties: {
					ok: { type: "boolean", required: true },
					summary: { type: "string", required: true },
					facts: { type: "array", items: { type: "string" } },
					coverage: { type: "string" },
				},
			},
			render: (_args, value) => [{
				type: "text",
				text: [
					value.summary,
					typeof value.coverage === "string" && value.coverage.length > 0 ? `coverage: ${value.coverage}` : "",
					...(value.facts ?? []),
				].filter((line) => line.length > 0).join("\n"),
			}],
		},
		async execute(args, exec) {
			const api = await ready;
			if (store === null || api === null) {
				return { ok: false, summary: `ontology unavailable: ${initError ?? "store not open"}` };
			}
			const action = String(args.action ?? "").trim();
			const sessionId = exec?.agent?.session?.header?.id;
			const sourceRef = typeof sessionId === "string" && sessionId.length > 0 ? `session:${sessionId}` : null;
			const requestedSource = String(args.source_kind ?? "").trim();
			const sourceKind = requestedSource === "user" || requestedSource === "system" ? requestedSource : "model";
			try {
				if (action === "remember") {
					const outcome = api.remember(store, {
						subject: args.subject,
						predicate: args.predicate,
						object: args.object,
						qualifier: args.qualifier,
						effectiveAt: args.effective_at,
						source: sourceKind,
						sourceKind,
						sourceRef,
					});
					writeSnapshot();
					const line = factLine(api, outcome.fact);
					if (outcome.duplicate) return { ok: true, summary: `already known: ${line}` };
					const superseded = outcome.superseded.length === 0
						? ""
						: ` (superseded ${outcome.superseded.length} older value${outcome.superseded.length === 1 ? "" : "s"})`;
					const prefix = outcome.historical === true ? "recorded historical" : "remembered";
					return { ok: true, summary: `${prefix}: ${line}${superseded}` };
				}
				if (action === "correct") {
					const outcome = api.correct(store, {
						factId: args.fact_id,
						object: args.object,
						qualifier: args.qualifier,
						effectiveAt: args.effective_at,
						source: sourceKind,
						sourceKind,
						sourceRef,
					});
					writeSnapshot();
					return {
						ok: true,
						summary: `${outcome.historical === true ? "recorded historical" : "corrected"}: ${factLine(api, outcome.fact)} (replaced ${outcome.replaced.id})`,
					};
				}
				if (action === "forget") {
					const factId = String(args.fact_id ?? "").trim();
					const query = String(args.query ?? "").trim();
					const subject = String(args.subject ?? "").trim();
					const predicate = String(args.predicate ?? "").trim();
					if (factId.length === 0 && query.length === 0 && subject.length === 0 && predicate.length === 0) {
						return { ok: false, summary: "forget needs fact_id, query, subject, or predicate; refusing to wipe the ontology" };
					}
					const outcome = api.forget(store, {
						factId,
						query,
						subject,
						predicate,
						hard: args.hard === true,
					});
					writeSnapshot();
					return {
						ok: true,
						summary: outcome.count === 0
							? "no matching facts"
							: `${outcome.hard ? "deleted" : "forgot"} ${outcome.count} fact${outcome.count === 1 ? "" : "s"}`,
						facts: outcome.ids,
					};
				}
				if (action === "search") {
					const rows = api.search(store, {
						query: args.query,
						subject: args.subject,
						predicate: args.predicate,
						limit: args.limit,
						history: args.history === true,
					});
					const knownSubject = typeof args.subject === "string" && args.subject.trim().length > 0
						? api.findEntity(store, args.subject) !== null
						: null;
					const coverage = rows.length > 0 ? "exact" : knownSubject === true ? "partial" : "none";
					const summary = rows.length > 0
						? `${rows.length} matching fact${rows.length === 1 ? "" : "s"}`
						: coverage === "partial"
							? "the entity is known but this fact is not recorded; missing is not false"
							: "no record; this is not evidence that the fact is false";
					return {
						ok: true,
						summary,
						coverage,
						facts: rows.map((fact) => factLine(api, fact)),
					};
				}
				if (action === "list") {
					const overview = api.overview(store);
					const lines = [
						...overview.pinned.map((fact) => `📌 ${factLine(api, fact)}`),
						...overview.recent
							.filter((fact) => overview.pinned.every((pinned) => pinned.id !== fact.id))
							.map((fact) => factLine(api, fact)),
					];
					return {
						ok: true,
						summary: `${overview.counts.facts} facts · ${overview.counts.entities} entities · ${overview.counts.pinned} pinned · version ${overview.version}`,
						facts: lines,
					};
				}
				if (action === "describe") {
					const wanted = String(args.predicate ?? args.name ?? "").trim();
					if (wanted.length === 0) {
						return { ok: true, summary: "predicate catalog", facts: describeCatalog().split("\n") };
					}
					const spec = predicateCatalog().find((entry) => entry.name === wanted);
					if (spec === undefined) {
						const guesses = suggestPredicate(wanted);
						const hint = guesses.length > 0 ? `; did you mean ${guesses.join(" / ")}?` : "";
						return { ok: false, summary: `unknown predicate ${JSON.stringify(wanted)}${hint}` };
					}
					const flags = `${spec.kind}/${spec.cardinality}${spec.pinned ? "/pinned" : ""}`;
					return {
						ok: true,
						summary: `${spec.name} (${flags})`,
						facts: [
							spec.about,
							`synonyms: ${spec.synonyms.join(", ")}`,
							`examples: ${spec.examples.join(", ")}`,
						],
					};
				}
				if (action === "related") {
					const graph = api.related(store, {
						entity: args.entity ?? args.subject,
						depth: args.depth,
						predicates: args.predicates,
						limit: args.limit,
					});
					const lines = [];
					for (const node of graph.nodes) {
						lines.push(`${node.entity.name} (${node.entity.kind}) [${node.entity.id}]`);
						for (const fact of node.facts) lines.push(`  · ${factLine(api, fact)}`);
						for (const edge of node.edges) {
							const arrow = edge.direction === "out" ? "→" : "←";
							const role = edge.qualifier.length > 0 ? ` (${edge.qualifier})` : "";
							lines.push(`  ${arrow} ${edge.predicate}${role} ${edge.other.name}`);
						}
					}
					return {
						ok: true,
						summary: `${graph.nodes.length} node${graph.nodes.length === 1 ? "" : "s"} from ${graph.root.name}${graph.truncated ? " (truncated)" : ""}`,
						facts: lines,
					};
				}
				if (action === "metric") {
					const result = runMetric(store, {
						name: args.name,
						subject: args.subject,
						predicate: args.predicate,
					});
					return {
						ok: true,
						summary: `${result.name} = ${result.value} ${result.unit} (${result.rule})`,
						facts: result.inputs.map((fact) => factLine(api, fact)),
					};
				}
				if (action === "export") {
					const format = String(args.format ?? "markdown").trim();
					if (format !== "markdown" && format !== "json" && format !== "turtle" && format !== "bundle") {
						return { ok: false, summary: `unknown format ${JSON.stringify(format)}; use markdown | json | turtle | bundle` };
					}
					const written = exportOntology(format, args.to_workspace === true);
					const where = written.workspacePath === null ? written.path : `${written.path} and ${written.workspacePath}`;
					return {
						ok: true,
						summary: `wrote ${where} (${written.bytes} bytes, ${format})`,
					};
				}
				if (action === "import") {
					const outcome = importOntologyFile(args.path);
					const conflicts = Array.isArray(outcome.conflicts) ? outcome.conflicts : [];
					return {
						ok: true,
						summary: `imported ${outcome.imported}, skipped ${outcome.skipped}, superseded ${outcome.superseded}, historical ${outcome.historical}, retracted ${outcome.retracted}, entities +${outcome.entitiesCreated}, conflicts ${conflicts.length}`,
						facts: [
							outcome.path,
							...conflicts.map((conflict) => `${conflict.predicate}: local ${conflict.local} vs incoming ${conflict.incoming}; kept ${conflict.kept} (${conflict.reason})`),
						],
					};
				}
				if (action === "migrate_profile") {
					const outcome = migrateLegacyProfile(args.apply === true);
					return {
						ok: outcome.ok,
						summary: outcome.message,
						facts: outcome.preview,
					};
				}
				return { ok: false, summary: `unknown action ${JSON.stringify(action)}; use remember | correct | forget | search | list | describe | related | metric | export | import | migrate_profile` };
			} catch (error) {
				return { ok: false, summary: String(error?.message ?? error) };
			}
		},
	}));

	ctx.on("agent/pre-step", async ({ agent, turn, step, signal }, next) => {
		const decision = await next();
		if (decision.kind === "reject" || signal?.aborted) return decision;
		await ready;
		if (store === null || storeApi === null) return decision;
		const version = storeApi.getVersion(store);
		const previous = injected.get(agent);
		if (previous !== undefined && previous.version === version) return decision;
		const overview = storeApi.overview(store);
		const signature = createHash("sha1")
			.update(JSON.stringify(overview.pinned.map((fact) => [fact.id, fact.object, fact.qualifier])))
			.digest("hex");
		if (previous !== undefined && previous.signature === signature) {
			injected.set(agent, { version, signature, hadPinned: previous.hadPinned });
			return decision;
		}
		injected.set(agent, { version, signature, hadPinned: overview.pinned.length > 0 });
		if (overview.pinned.length === 0) {
			if (previous?.hadPinned === true) {
				logInjection(agent?.session?.header?.id, turn, step, [], true);
				return {
					...decision,
					messages: [
						...decision.messages,
						createUserMessage({
							content: [{ type: "text", text: "Pinned ontology facts were all removed; do not apply any earlier pinned snapshot." }],
							source: { kind: name, form: "snapshot", sections: [{ name, text: "pinned facts removed" }] },
						}),
					],
				};
			}
			return decision;
		}
		const text = renderPinned(overview.pinned);
		if (text.length === 0) return decision;
		logInjection(agent?.session?.header?.id, turn, step, overview.pinned, false);
		return {
			...decision,
			messages: [
				...decision.messages,
				createUserMessage({
					content: [{ type: "text", text }],
					source: { kind: name, form: "snapshot", sections: [{ name, text }] },
				}),
			],
		};
	}, { prepend: true });
}

export { apply, inject, name };
